cd /tmp/w; python3 << 'EOF'
import json
meds={}
for l in open('Medication.ndjson'):
    m=json.loads(l)
    name=None
    for idf in m.get('identifier',[]):
        if idf['system'].endswith('mimic-medication-name'): name=idf['value']
    if not name: name=m.get('code',{}).get('text')
    meds[m['id']]=name
json.dump(meds,open('meds.json','w'))
print(sum(1 for v in meds.values() if not v))
kw=['warfarin','coumadin','apixaban','eliquis','rivaroxaban','xarelto','dabigatran','pradaxa','edoxaban','heparin','enoxaparin','lovenox','fondaparinux','argatroban','bivalirudin','citalopram','escitalopram','haloperidol','methadone','amiodarone','sotalol','dofetilide']
hits={k:set() for k in kw}
for i,n in meds.items():
    if not n: continue
    nl=n.lower()
    for k in kw:
        if k in nl: hits[k].add(n)
for k,v in hits.items():
    print(k, sorted(v))
EOF

