from final import *
import numpy as np, json
from collections import defaultdict
ecgs=json.load(open('ecgs.json'))['ecgs']
pats={p['id']:p for p in json.load(open('patients.json'))['resources']}
bp=defaultdict(list)
for e in ecgs: bp[e['patient']].append(e)
targets=[]
for p,v in bp.items():
    if pats[p].get('deceasedDateTime'): continue
    v.sort(key=lambda x:x['time']); targets.append((p,v[-1]['ecg']))
for p,eid in sorted(targets):
    r=analyze(eid); mb,on,off=r['_mb'],r['_on'],r['_off']
    res={}
    for l in ['I','aVF','II','III','aVL','aVR']:
        li=LEADS.index(l); seg=mb[on:off,li]
        res[l]=(float(seg.sum()/FS*1000), float(seg.max()+seg.min()))
